CREATE EXTENSION pgrowlocks;

BEGIN;
WITH next_job AS (
  SELECT job_id FROM jobs
   WHERE status = 'pending'
   ORDER BY job_id LIMIT 1
)
SELECT * FROM next_job FOR UPDATE SKIP LOCKED;

SELECT locked_row, modes FROM pgrowlocks('jobs');
ROLLBACK;

BEGIN;
WITH next_job AS (
  SELECT job_id FROM jobs
   WHERE status = 'pending'
   ORDER BY job_id LIMIT 1
     FOR UPDATE SKIP LOCKED
)
SELECT * FROM next_job;

SELECT locked_row, modes FROM pgrowlocks('jobs');
ROLLBACK;

CREATE INDEX jobs_pending_idx
    ON jobs (priority DESC, job_id)
 WHERE status = 'pending';
